    {
      "category": "network_architecture",
      "rationale": "Normalize reset, update and candidate preactivations inside each GRU cell to stabilize gate scales. Preserve PyTorch's reset convention, hidden width, layer count, inter-layer dropout, embeddings, readout, scoring, loss and optimizer. The predictor already imports GRU4RecModel from train.py, so it loads the same architecture and one checkpoint per dataset. Script the recurrent loop to reduce Python overhead.",
      "edits": [
        {
          "find": "class GRU4RecModel(nn.Module):",
          "replace": "@torch.jit.script
def _normalized_gru_rollout(projected: torch.Tensor, hidden: torch.Tensor,
                            weight_hh: torch.Tensor, bias_hh: torch.Tensor,
                            reset_weight: torch.Tensor, reset_bias: torch.Tensor,
                            update_weight: torch.Tensor, update_bias: torch.Tensor,
                            candidate_weight: torch.Tensor, candidate_bias: torch.Tensor):
    outputs: list[torch.Tensor] = []
    width = hidden.size(1)
    for step in range(projected.size(1)):
        input_reset, input_update, input_candidate = projected[:, step].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_candidate = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = torch.sigmoid(torch.nn.functional.layer_norm(
            input_reset + hidden_reset, [width], reset_weight, reset_bias, 1e-5
        ))
        update = torch.sigmoid(torch.nn.functional.layer_norm(
            input_update + hidden_update, [width], update_weight, update_bias, 1e-5
        ))
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            input_candidate + reset * hidden_candidate,
            [width], candidate_weight, candidate_bias, 1e-5
        ))
        hidden = (1.0 - update) * candidate + update * hidden
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class LayerNormalizedGRU(nn.Module):
    def __init__(self, hidden_units: int, num_layers: int, dropout: float):
        super().__init__()
        self.hidden_units = hidden_units
        self.dropout = dropout
        self.cells = nn.ModuleList([
            nn.GRUCell(hidden_units, hidden_units) for _ in range(num_layers)
        ])
        self.gate_norms = nn.ModuleList([
            nn.ModuleList([nn.LayerNorm(hidden_units) for _ in range(3)])
            for _ in range(num_layers)
        ])

    def forward(self, inputs: torch.Tensor):
        out = inputs
        final_states = []
        for layer, (cell, norms) in enumerate(zip(self.cells, self.gate_norms)):
            projected = torch.nn.functional.linear(out, cell.weight_ih, cell.bias_ih)
            hidden = out.new_zeros((out.size(0), self.hidden_units))
            out, hidden = _normalized_gru_rollout(
                projected, hidden, cell.weight_hh, cell.bias_hh,
                norms[0].weight, norms[0].bias,
                norms[1].weight, norms[1].bias,
                norms[2].weight, norms[2].bias,
            )
            final_states.append(hidden)
            if layer + 1 < len(self.cells):
                out = torch.nn.functional.dropout(
                    out, p=self.dropout, training=self.training
                )
        return out, torch.stack(final_states, dim=0)


class GRU4RecModel(nn.Module):"
        },
